            array('title' => 'কারিগরি শিক্ষাবোর্ডের নতুন পলিটেকনিক কারিকুলাম প্রকাশ', 'content' => 'রোবোটিক্স, এআই এবং এভিয়েশন ইঞ্জিনিয়ারিং বিষয়ে ডিপ্লোমা কোর্স অন্তর্ভুক্ত করার নতুন সিদ্ধান্ত...', 'cat' => 'education'),
        );

        foreach ($sample_posts as $post_data) {
            $cat_id = isset($cat_ids[$post_data['cat']]) ? $cat_ids[$post_data['cat']] : 0;
            $content = isset($post_data['content']) ? $post_data['content'] : '';
            wp_insert_post(array(
                'post_title'    => $post_data['title'],
                'post_content'  => $content,
                'post_status'   => 'publish',
                'post_type'     => 'post',
                'post_category' => array($cat_id),
            ));
        }

        // Mark demo as imported
        update_option('mughdo_demo_imported', true);
        update_option('mughdo_demo_import_date', current_time('mysql'));

        wp_send_json_success('১০০+ ডেমো ডাটা সম্পূর্ণ ইমপোর্ট হয়েছে!');
    }

    public static function ajax_reset_demo_flag() {
        check_ajax_referer('mughdo_demo_nonce', '_nonce');
        delete_option('mughdo_demo_imported');
        wp_send_json_success('ফ্ল্যাগ রিকভার করা হয়েছে।');
    }
}

Mughdo_Demo_Importer::init();
